-- =============================================================================
-- Metric catalogue. canonical_key groups metrics whose definition AND unit match
-- across providers; dashboard aggregation only ever sums within one canonical_key.
-- Platform-specific metrics get a platform-prefixed canonical key so they are never
-- added to another platform's metric (e.g. Instagram views != YouTube views).
-- Sources and check dates: docs/integrations/*.md
-- =============================================================================
INSERT INTO metric_definition (metric_key, provider, source_metric, canonical_key, scope, label, description, unit, measure_type, api_source) VALUES
